// ─── LEVELS ───────────────────────────────────────────────────────────────────
const LEVEL_THRESHOLDS = [
  {level:1, name:'Newcomer',      xp:0},
  {level:2, name:'Survival Mode', xp:100},
  {level:3, name:'Getting Around',xp:300},
  {level:4, name:'Daily Life',    xp:700},
  {level:5, name:'Comfortable',   xp:1500},
  {level:6, name:'Fluent',        xp:3500},
  {level:7, name:'Near-Native',   xp:7000},
];

function getLevelInfo(xp) {
  let current = LEVEL_THRESHOLDS[0];
  let next = LEVEL_THRESHOLDS[1];
  for (let i = 0; i < LEVEL_THRESHOLDS.length; i++) {
    if (xp >= LEVEL_THRESHOLDS[i].xp) {
      current = LEVEL_THRESHOLDS[i];
      next = LEVEL_THRESHOLDS[i+1] || null;
    }
  }
  const progress = next ? (xp - current.xp) / (next.xp - current.xp) : 1;
  return {level: current.level, name: current.name, progress, next};
}
